<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
const version=ref<Row|null>(null),status=ref<Row|null>(null),error=ref(''),notice=ref(''),busy=ref(false),confirming=ref(false)
const names:Record<string,string>={queued:'等待更新服务',downloading:'下载正式发布包',verifying:'校验发布包',backing_up:'备份数据库与文件',applying:'应用更新',checking:'检查新服务',succeeded:'更新成功',rolled_back:'已恢复上一版本',failed:'更新失败，原安装保留'}
const active=computed(()=>status.value?.items?.some((r:Row)=>!['succeeded','rolled_back','failed'].includes(r.state)))
const canUpdate=computed(()=>version.value?.update_available&&version.value?.current===status.value?.current&&status.value?.helper_ready&&!active.value&&!busy.value)
let disposed=false,timer:ReturnType<typeof setTimeout>|undefined
async function refresh(){const data=await props.api('panel-updates');if(disposed)return;const changed=status.value?.current&&status.value.current!==data.current;status.value=data;if(changed){version.value=null;version.value=await props.api('panel-release')}}
async function check(){if(busy.value)return;busy.value=true;error.value='';try{await refresh();version.value=await props.api('panel-release')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function update(){if(!canUpdate.value)return;busy.value=true;error.value='';confirming.value=false;try{await props.api('panel-updates','POST',{version:version.value!.latest,current:status.value!.current});notice.value='更新已排队。服务重启期间可能暂时断开，请保留页面，状态会自动恢复。';await refresh()}catch(e){error.value=String(e)}finally{busy.value=false}}
function schedule(){timer=setTimeout(async()=>{if(disposed)return;if(document.visibilityState!=='hidden')try{await refresh()}catch{if(active.value)notice.value='正在等待更新服务恢复。独立更新服务会继续执行，请勿重复提交。'};if(!disposed)schedule()},active.value?3000:10000)}
onMounted(()=>{void check();schedule()});onUnmounted(()=>{disposed=true;clearTimeout(timer)})
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>后台版本与更新</h2><p class="muted">使用 GitHub 正式发布包更新，自动校验并备份数据库与文件。仅主管理员可操作。</p></div><button class="secondary" :disabled="busy" @click="check">{{busy?'正在处理…':'检查更新'}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="fields"><div><small class="block-muted">当前运行版本</small><strong>{{status?.current||version?.current||'查询中'}}</strong></div><div><small class="block-muted">GitHub 最新正式版</small><strong>{{version?.latest||'尚未获取'}}</strong></div><div><small class="block-muted">本机更新服务</small><strong>{{status?.helper_ready?'已就绪':'未就绪 / 暂未回报'}}</strong></div></div><p v-if="status&&!status.helper_ready" class="form-note">自动更新需要独立的本机服务。Linux systemd 安装支持自动更新；Windows、Compose 及其他安装方式请使用对应的手动升级流程。</p><p v-if="version&&!version.update_available" class="notice">当前版本已是最新，或高于最新正式版。</p><div class="row-actions"><button class="primary" :disabled="!canUpdate" @click="confirming=true">更新到 {{version?.latest||'最新版本'}}</button><a v-if="version" :href="version.release_url" target="_blank" rel="noopener noreferrer">查看正式发布说明</a></div><p class="muted">更新会短暂重启管理端；总管理机上的托管 Agent 如在运行，也会随安装方式重启。其他 VPS 的 Agent 版本需单独维护。校验失败保留原版本；应用后健康检查失败会恢复数据库与文件备份。更新过程由独立服务完成，关闭网页不会取消任务。</p><div v-for="job in status?.items??[]" :key="job.id" class="setting-row"><div><b>{{job.from_version}} → {{job.target_version}}</b><small class="block-muted">{{names[job.state]||job.state}} · {{new Date(job.updated_at).toLocaleString()}}</small><small v-if="job.detail" class="block-muted">{{job.detail}}</small></div></div><p v-if="status&&!status.items?.length" class="console-empty">尚无后台更新记录</p></section><div v-if="confirming" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="确认后台更新"><div class="form-content"><h2>更新到 {{version?.latest}}？</h2><p>当前版本 {{status?.current}}。将下载项目正式发布包、校验 SHA-256、备份数据库和文件，然后重启服务验证。期间面板和总管理机托管代理可能短暂不可用。</p><p>失败时保留诊断与备份，并尝试恢复上一版本。请先确认 GitHub 发布说明中的兼容性要求。</p></div><div class="modal-footer"><button class="secondary" @click="confirming=false">取消</button><button class="primary" :disabled="!canUpdate" @click="update">确认更新</button></div></section></div></template>
